// ─── File: src/test/java/com/bank/hashset/HashSetInternalsTest.java ───
package com.bank.hashset;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class HashSetInternalsTest {

    // ═══ Prove HashSet is backed by HashMap ═══
    @Test
    void backedByHashMap() throws Exception {
        HashSet<String> set = new HashSet<>();
        Field mapField = HashSet.class.getDeclaredField("map");
        mapField.setAccessible(true);
        Object internal = mapField.get(set);
        assertThat(internal).isInstanceOf(HashMap.class);
        // Proof: HashSet literally contains a HashMap!
    }

    // ═══ add returns false for duplicates ═══
    @Test
    void add_rejectsDuplicates() {
        Set<String> set = new HashSet<>();
        assertThat(set.add("SAV2001")).isTrue();   // new → true
        assertThat(set.add("CUR3001")).isTrue();   // new → true
        assertThat(set.add("SAV2001")).isFalse();  // DUPLICATE → false!
        assertThat(set).hasSize(2);                // still 2!
    }

    // ═══ contains uses HashMap.containsKey ═══
    @Test
    void contains_O1() {
        Set<String> set = new HashSet<>(Set.of("SAV2001", "CUR3001", "FD4001"));
        assertThat(set.contains("SAV2001")).isTrue();    // O(1)!
        assertThat(set.contains("INVALID")).isFalse();   // O(1)!
    }

    // ═══ One null allowed ═══
    @Test
    void oneNullAllowed() {
        Set<String> set = new HashSet<>();
        assertThat(set.add(null)).isTrue();    // null → HashMap null key
        assertThat(set.add(null)).isFalse();   // duplicate null!
        assertThat(set).hasSize(1);
        assertThat(set.contains(null)).isTrue();
    }

    // ═══ Requires proper hashCode + equals ═══
    @Test
    void requiresHashCodeAndEquals() {
        record Account(String id) {}  // record: auto hashCode + equals!

        Set<Account> set = new HashSet<>();
        set.add(new Account("SAV2001"));
        set.add(new Account("SAV2001"));  // duplicate! equals() detects it.
        assertThat(set).hasSize(1);  // deduplicated!
    }

    // ═══ Performance: HashSet vs ArrayList for contains ═══
    @Test
    void performance_hashSetVsArrayList() {
        int n = 50_000;
        Set<Integer> set = new HashSet<>();
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < n; i++) { set.add(i); list.add(i); }

        // HashSet contains:
        long t1 = System.nanoTime();
        for (int i = 0; i < n; i++) set.contains(i);
        long setMs = (System.nanoTime() - t1) / 1_000_000;

        // ArrayList contains:
        long t2 = System.nanoTime();
        for (int i = 0; i < 1000; i++) list.contains(i);  // only 1K — too slow for 50K!
        long listMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("HashSet 50K lookups: " + setMs + "ms, ArrayList 1K lookups: " + listMs + "ms");
        // HashSet 50K: ~5ms. ArrayList 1K: ~100ms. HashSet is ~1000x faster!
    }
}
